package zombie.iso;
public class IsoObject{public String getSpriteName(){return sprite==null?null:sprite.name;}public zombie.iso.SpriteModel spriteModel;public zombie.iso.sprite.IsoSprite spriteModelInit;public static int lazyCalls;public zombie.iso.SpriteModel getSpriteModel(){lazyCalls++;throw new AssertionError("No native sprite-model builder");}public IsoGridSquare square;public zombie.iso.sprite.IsoSprite sprite=new zombie.iso.sprite.IsoSprite(),overlay;public IsoDirections dir=IsoDirections.N;public float rise;public boolean removed;public java.util.ArrayList<Object> attachedAnimSprite;public IsoObject(IsoGridSquare s){square=s;s.objects.add(this);}public IsoGridSquare getSquare(){return square;}public zombie.iso.sprite.IsoSprite getSprite(){return sprite;}public zombie.iso.sprite.IsoSprite getOverlaySprite(){return overlay;}public IsoDirections getDir(){return dir;}public int getObjectIndex(){return removed?-1:square.objects.indexOf(this);}}

